<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ArrowUpRight,Check,CheckCircle2,Crown,LockKeyhole,RefreshCw,RotateCcw,Save,SlidersHorizontal} from 'lucide-vue-next'
import {api,cash,notify} from '../lib'
const fee=ref(0),accepting=ref(false),busy=ref(false),loading=ref(true),error=ref('')
const saved=ref<{service_fee:number;accepting:boolean}>()
const amount=computed(()=>Math.round(Number(fee.value)*100))
const valid=computed(()=>fee.value!==null&&String(fee.value)!==''&&Number.isFinite(amount.value)&&amount.value>=0&&amount.value<=10000000)
const dirty=computed(()=>!!saved.value&&(amount.value!==saved.value.service_fee||accepting.value!==saved.value.accepting))
function restore(){if(saved.value){fee.value=saved.value.service_fee/100;accepting.value=saved.value.accepting;error.value=''}}
async function load(){loading.value=true;error.value='';try{const d=await api('/admin/refund/settings');saved.value={service_fee:d.service_fee,accepting:d.accepting};restore()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(!valid.value||!dirty.value||busy.value)return;busy.value=true;error.value='';const value={service_fee:amount.value,accepting:accepting.value};try{await api('/admin/refund/pricing','PUT',value);saved.value=value;notify('代退服务定价已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
 <div class="page-heading"><div><span class="eyebrow">OPERATIONS / PRICING</span><h1>服务与定价</h1><p>设置代退服务费与受理状态，会员优惠自动计算。</p></div><button class="icon-btn bordered" :disabled="loading||busy||dirty" @click="load" aria-label="刷新代退定价"><RefreshCw :size="18" :class="{spinning:loading}"/></button></div>
 <div v-if="error" class="alert danger" role="alert">{{error}}<button v-if="!saved" class="text-btn" @click="load">重新加载</button></div>
 <div v-if="loading&&!saved" class="panel pricing-loading" role="status"><RefreshCw :size="20" class="spinning"/>正在读取代退服务配置…</div>
 <form v-if="saved" class="refund-pricing" @submit.prevent="save">
  <fieldset :disabled="busy||loading">
   <div class="refund-pricing-grid">
    <section class="panel refund-service-card">
     <header class="refund-service-heading"><span class="refund-service-icon"><RotateCcw :size="23"/></span><div><h2>代退服务</h2><p>按账号计费 · 完成服务后结算</p></div><span class="refund-service-state" :class="{open:saved.accepting}"><i/>{{saved.accepting?'已开放受理':'暂未开放'}}</span></header>
     <div class="refund-price-editor">
      <label for="refund-standard-fee">标准服务费<span>每个账号的基础价格</span></label>
      <div class="refund-fee-input"><input id="refund-standard-fee" v-model.number="fee" type="number" min="0" max="100000" step="0.01" required aria-label="标准服务费" aria-describedby="refund-price-help"/><span>积分 / 账号</span></div>
      <p id="refund-price-help">客户实付按会员等级或账户专属价计算。</p>
     </div>
     <div class="refund-availability"><div><h3>开放代退申请</h3><p>开启后，用户可从办理页面和 API 提交申请。</p></div><button type="button" class="refund-switch" role="switch" aria-label="开放代退申请" :aria-checked="accepting" :class="{enabled:accepting}" @click="accepting=!accepting"><span><Check v-if="accepting" :size="12"/></span></button></div>
     <div class="refund-change-note"><LockKeyhole :size="16"/><p>每笔申请锁定提交时的价格。改价只影响新订单；关闭受理后，已有订单继续办理。</p></div>
     <footer class="refund-pricing-save"><span :class="{pending:dirty}"><i v-if="dirty"/><CheckCircle2 v-else :size="16"/>{{dirty?'有未保存的修改':'配置已同步'}}</span><div><button v-if="dirty" type="button" class="btn secondary" @click="restore">恢复修改</button><button class="btn primary" :disabled="busy||!dirty||!valid"><Save :size="16"/>{{busy?'保存中…':'保存服务定价'}}</button></div></footer>
    </section>
    <aside class="refund-pricing-aside">
     <section class="panel refund-pricing-rules"><div class="refund-rules-title"><Crown :size="20"/><h2>会员与结算</h2></div><p class="refund-rules-intro">沿用星桥统一会员与积分钱包。</p><div class="refund-member-note"><b>会员优惠自动生效</b><p>等级折扣应用于标准服务费；有账户专属价时，优先使用专属价。</p><a href="#/admin/membership">管理会员权益<ArrowUpRight :size="14"/></a></div><ol class="refund-settlement"><li><span>1</span><div><b>提交申请</b><p>按实际服务费冻结积分</p></div></li><li><span>2</span><div><b>服务完成</b><p>冻结积分转为扣费，结算一次</p></div></li><li><span>3</span><div><b>未完成服务</b><p>最终失败或排队取消后释放</p></div></li></ol></section>
     <a class="panel refund-resource-link" href="#/admin/refund"><span class="refund-resource-icon"><SlidersHorizontal :size="19"/></span><div><b>资源与调度</b><p>管理母号、代理与执行队列</p></div><ArrowUpRight :size="17"/></a>
    </aside>
   </div>
  </fieldset>
 </form>
</template>
